"""Error-class breakdown for each task over a recorded run."""
import json, sys, collections, re
sys.path.insert(0, "/workspace/harness/solver")
sys.path.insert(0, "/workspace")
import tools.memory as mem
from tools.memory import AnswerSpace, load_examples


def charges(text):
    text = str(text).strip()
    m = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if m:
        text = m.group(1).strip()
    text = re.sub(r"<eoa>.*", "", text).strip()
    for sep in [";", "；", ",", "，", "、"]:
        if sep in text:
            return {p.strip() for p in text.split(sep) if p.strip()}
    return {text} if text else set()


def main(run):
    rows = [json.loads(l) for l in open(f"/workspace/runs/{run}/results/samples.jsonl")]
    for task in ["USPTO", "Symptom2Disease", "LawBench"]:
        tr = [r for r in rows if r["task"] == task and r["status"] == "ok"]
        wrong = [r for r in tr if not r["was_correct"]]
        mem.MEMORY_PATH = f"/workspace/runs/{run}/{task}/memory.json"
        space = AnswerSpace(load_examples())
        cnt = collections.Counter()
        print(f"--- {task}: {len(wrong)} wrong of {len(tr)}")
        for r in wrong:
            p, t = r["prediction"], r["target"]
            if task == "LawBench":
                ps, ts = charges(p), charges(t)
                if ps < ts:
                    key = "subset(missing " + str(len(ts) - len(ps)) + ")"
                elif ps > ts:
                    key = "superset"
                elif ps & ts:
                    key = "overlap"
                else:
                    key = "disjoint"
                cnt[key] += 1
                if key.startswith("subset") and len(ts) == 1:
                    cnt["subset-single-target"] += 1
            else:
                if p.strip() == t.strip():
                    key = "exact-but-wrong"
                elif p.strip().lower() == t.strip().lower():
                    key = "case-only"
                else:
                    key = "content"
                cnt[key] += 1
        print("   ", dict(cnt))


if __name__ == "__main__":
    for r in sys.argv[1:]:
        main(r)

