"""How good is the harness's ranking, measured as k-NN answer accuracy on val."""
import json, sys, collections
sys.path.insert(0, "/workspace/harness/solver")
sys.path.insert(0, "/workspace")
import tools.memory as mem
from tools.memory import AnswerSpace, load_examples, Ranker, example_text
from benchmark.evaluate import load_task
from benchmark.runtime.runs import load_config
from pathlib import Path
import re


def charges(text):
    text = str(text).strip()
    m = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if m:
        text = m.group(1).strip()
    text = re.sub(r"<eoa>.*", "", text).strip()
    for sep in [";", "；", ",", "，", "、"]:
        if sep in text:
            return frozenset(p.strip() for p in text.split(sep) if p.strip())
    return frozenset([text]) if text else frozenset()


def main(run, task):
    cfg = load_config(Path("/workspace/runs/config.yaml"))
    examples = load_task(task, cfg, "val")
    mem.MEMORY_PATH = f"/workspace/runs/{run}/{task}/memory.json"
    train = load_examples()
    ranker = Ranker(train)
    hits = collections.Counter()
    n = len(examples)
    for ex in examples:
        order = ranker.rank(ex["input"])
        if task == "LawBench":
            tgt = charges(ex["target"])
            for k in (1, 3, 5, 10, 20, 50):
                if any(charges(train[i]["target"]) == tgt for i in order[:k]):
                    hits[f"top{k}"] += 1
        else:
            tgt = str(ex["target"]).strip()
            for k in (1, 3, 5, 10, 20, 50):
                if any(str(train[i]["target"]).strip() == tgt for i in order[:k]):
                    hits[f"top{k}"] += 1
    print(f"{task} n={n}", {k: hits[k] for k in sorted(hits)})
    # how many val targets exist in memory at all
    if task == "LawBench":
        held = sum(1 for ex in examples if charges(ex["target"]) <= {c for e in train for c in charges(e["target"])})
        exact = sum(1 for ex in examples if any(charges(e["target"]) == charges(ex["target"]) for e in train))
        print("   targets whose charges all exist in memory:", held, " exact set held:", exact)
    else:
        held = sum(1 for ex in examples if str(ex["target"]).strip() in {str(e["target"]).strip() for e in train})
        print("   targets held verbatim in memory:", held)


if __name__ == "__main__":
    run = sys.argv[1]
    for t in (sys.argv[2:] or ["USPTO", "Symptom2Disease", "LawBench"]):
        main(run, t)

