"""Would correcting a predicted USPTO fragment to the memory's nearest fragment flip samples?"""
import json, sys, glob, collections
sys.path.insert(0, "/workspace/harness/solver")
sys.path.insert(0, "/workspace")
import tools.memory as mem
from tools.memory import load_examples
from benchmark.data.evaluators import eval_uspto


def lev(a, b, cap=3):
    if abs(len(a) - len(b)) > cap:
        return cap + 1
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]


def main(runs):
    total = gained = 0
    stats = collections.Counter()
    for run in runs:
        mem.MEMORY_PATH = f"/workspace/runs/{run}/USPTO/memory.json"
        ex = load_examples()
        vocab = set()
        for e in ex:
            for frag in str(e["target"]).split("."):
                frag = frag.strip().lower()
                if frag:
                    vocab.add(frag)
        rows = [json.loads(l) for l in open(f"/workspace/runs/{run}/results/samples.jsonl")]
        for r in rows:
            if r["task"] != "USPTO" or r["status"] != "ok":
                continue
            total += 1
            pred = str(r["prediction"]).strip()
            frags = [f.strip() for f in pred.split(".") if f.strip()]
            near = []
            for f in frags:
                if f.lower() in vocab:
                    stats["exact-fragment"] += 1
                    near.append(f)
                    continue
                cand = [v for v in vocab if lev(f.lower(), v) <= 2]
                if len(cand) == 1:
                    stats["near-unique"] += 1
                    near.append(cand[0])
                else:
                    stats["unknown" if not cand else "near-ambiguous"] += 1
                    near.append(f)
            fixed = ".".join(near)
            was = eval_uspto(pred, r["target"])["correct"]
            now = eval_uspto(fixed, r["target"])["correct"]
            if not was and now:
                gained += 1
                print("GAIN", run[:8], r["example_index"], r["sample_index"], pred[:60], "->", fixed[:60])
            if was and not now:
                print("LOSS", run[:8], r["example_index"], r["sample_index"], pred[:60])
    print("samples", total, "gained", gained, stats)


if __name__ == "__main__":
    main(sys.argv[1:] or [d.split("/")[3] for d in glob.glob("/workspace/runs/*/results/samples.jsonl")])

