"""Samples whose check_answer draft would have scored right while the final answer did not."""
import json, glob, sys, collections
sys.path.insert(0, "/workspace")
from benchmark.data.evaluators import get_evaluator, extract_final_answer


def correct(task, pred, target):
    r = get_evaluator(task)(pred, target)
    return r["was_correct"] if isinstance(r, dict) else bool(r)


counts = collections.Counter()
examples = []
for f in sorted(glob.glob("/workspace/runs/*/results/samples.jsonl")):
    run = f.split("/")[3][:8]
    for line in open(f):
        r = json.loads(line)
        if r["status"] != "ok":
            continue
        task = r["task"]
        path = f"/workspace/runs/{f.split('/')[3]}/{task}/conversations/{r['example_index']:04d}/sample-{r['sample_index']}.json"
        try:
            d = json.load(open(path))
        except Exception:
            continue
        drafts = []
        for m in d["messages"]:
            for tc in (m.get("tool_calls") or []):
                name = tc.get("name") or (tc.get("function") or {}).get("name")
                if name != "check_answer":
                    continue
                args = tc.get("args") or (tc.get("function") or {}).get("arguments")
                if isinstance(args, str):
                    try:
                        args = json.loads(args)
                    except Exception:
                        args = {"draft": args}
                drafts.append(str((args or {}).get("draft", "")))
        if not drafts:
            continue
        counts[(task, "has-draft")] += 1
        if r["was_correct"]:
            continue
        good = [x for x in drafts if correct(task, x, r["target"])]
        if good:
            counts[(task, "draft-right-final-wrong")] += 1
            examples.append((run, task, r["example_index"], r["sample_index"], good[-1][:70], (r["prediction"] or "")[:70], r["target"][:70]))
print(dict(counts))
for e in examples[:25]:
    print(e)
print("total lost:", len(examples))

