"""Construct the tip's agent for each task the way the worker does, with a stub model."""
import sys, json, importlib.util
sys.path.insert(0, "/workspace")
from pathlib import Path
import shutil

STAGE = Path("/tmp/rt/stage2")


class Prefixed(type(Path())):
    def __new__(cls, *args):
        p = str(args[0])
        if p.startswith("/harness"):
            args = (str(STAGE) + p[len("/harness"):], *args[1:])
        return super().__new__(cls, *args)


def stage(run_id, task):
    if STAGE.exists():
        shutil.rmtree(STAGE)
    shutil.copytree("/workspace/harness/solver", STAGE, ignore=shutil.ignore_patterns("__pycache__"))
    (STAGE / "memory").mkdir(exist_ok=True)
    shutil.copyfile(f"/workspace/runs/{run_id}/{task}/memory.json", STAGE / "memory" / "memory.json")


class StubModel:
    """Enough of a BaseChatModel for construction; never called."""

    def __init__(self):
        from langchain_core.language_models.fake_chat_models import GenericFakeChatModel
        self.inner = GenericFakeChatModel(messages=iter([]))

    def __getattr__(self, name):
        return getattr(self.inner, name)


def main(run_id):
    from benchmark.evaluate import load_task
    from benchmark.runtime.runs import load_config
    cfg = load_config(Path("/workspace/runs/config.yaml"))
    for task in ["USPTO", "Symptom2Disease", "LawBench"]:
        stage(run_id, task)
        sys.path.insert(0, str(STAGE))
        for name in list(sys.modules):
            if name in {"agent", "middleware", "tools"} or name.startswith(("tools.", "middleware")):
                del sys.modules[name]
        spec = importlib.util.spec_from_file_location("agent", str(STAGE / "agent.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        mod.Path = Prefixed
        import tools.memory as mem
        mem.MEMORY_PATH = str(STAGE / "memory" / "memory.json")
        tools, memory = mod.build_tools(load_task(task, cfg, "val")[0]["input"])
        prompt = mod.render_prompt("QUESTION", memory)
        agent, prompt2 = None, None
        try:
            agent, prompt2 = mod.build_agent(StubModel(), "QUESTION", cfg["solver"])
            built = "built"
        except Exception as e:
            built = f"{type(e).__name__}: {e}"
        print(f"{task}: tools={[getattr(t,'name','?') for t in tools]} "
              f"check={memory['check_answer']} complete={memory['complete_listing']} "
              f"repeats={memory['spelling'] is not None} prompt={len(prompt)} -> build_agent: {built}")
        # exercise with_prompt both ways
        if agent is not None:
            inputs = {"messages": [{"role": "user", "content": prompt2 + "APPENDED"}]}
            out = mod.with_prompt(inputs, prompt2, prompt2)
            assert out["messages"][0]["content"] == prompt2 + "APPENDED", "identity failed"
            assert inputs["messages"][0]["content"].endswith("APPENDED")
            out2 = mod.with_prompt(inputs, prompt2 + "X", prompt2)
            assert out2["messages"][0]["content"] == prompt2 + "X" + "APPENDED", out2["messages"][0]["content"][-40:]
            print("   with_prompt: identity and swap verified")


if __name__ == "__main__":
    main(sys.argv[1])

